<?php
$pricingDocuments=[];
foreach(is_array($property['pricing_documents']??null)?$property['pricing_documents']:[] as $document){
    if(!is_array($document)||!is_string($document['url']??null))continue;
    $url=$document['url'];
    if(!preg_match('~^\./assets/(?:uploads|documents)/[a-zA-Z0-9_-]+\.(pdf|png|jpg|jpeg|webp)$~i',$url,$match))continue;
    $document['type']=strtolower($match[1])==='pdf'?'pdf':'image';$pricingDocuments[]=$document;
}
$nearby=$property['nearest_locations']??[];
if(is_string($nearby)){$nearby=array_map(static function($line){$parts=explode('|',$line,2);return ['name'=>trim($parts[0]),'distance'=>trim($parts[1]??'')];},preg_split('/\R/',trim($nearby)));}
if(!is_array($nearby))$nearby=[];
?>
<section class="pd-section" aria-labelledby="pd-pricing-title"><h2 id="pd-pricing-title">Pricing Documents</h2>
<?php if($pricingDocuments): ?><div class="pd-document-list"><?php foreach($pricingDocuments as $document): $name=is_string($document['name']??null)?$document['name']:'Pricing document'; ?><article class="pd-document-sheet"><?php if($document['type']==='image'): ?><a href="<?= e($document['url']) ?>" target="_blank" rel="noopener" data-document-view data-document-type="image" data-document-title="<?= e($name) ?>" aria-label="Open <?= e($name) ?>"><img src="<?= e($document['url']) ?>" alt="<?= e($name) ?>" loading="lazy"></a><?php else: ?><div class="pd-document-preview"><iframe src="<?= e($document['url']) ?>#toolbar=0&amp;navpanes=0&amp;view=FitH" title="Preview: <?= e($name) ?>" loading="lazy" tabindex="-1"></iframe><a class="pd-document-preview-open" href="<?= e($document['url']) ?>" data-document-view data-document-type="pdf" data-document-title="<?= e($name) ?>" aria-label="View <?= e($name) ?>"><span>PDF ? View document &nearr;</span></a></div><?php endif; ?><h3><?= e($name) ?></h3><div><a href="<?= e($document['url']) ?>" target="_blank" rel="noopener" data-document-view data-document-type="<?= e($document['type']) ?>" data-document-title="<?= e($name) ?>">View <?= $document['type']==='pdf'?'PDF':'image' ?> &nearr;</a><a href="<?= e($document['url']) ?>" download>Download</a></div></article><?php endforeach; ?></div><?php else: ?><p>Pricing documents have not been added yet. <a href="#contact-property">Request pricing information</a> from Royalmark Estate.</p><?php endif; ?></section>
<section class="pd-section" aria-labelledby="pd-nearest-title"><h2 id="pd-nearest-title">Nearest Locations</h2><div class="pd-nearby-grid"><?php $nearbyCount=0;foreach($nearby as $place): if(!is_array($place)||!is_string($place['name']??null)||trim($place['name'])==='')continue;$nearbyCount++; ?><article class="pd-nearby-place"><?= listingIcon('location') ?><div><h3><?= e($place['name']) ?></h3><?php if(is_string($place['distance']??null)&&$place['distance']!==''): ?><p><?= e($place['distance']) ?></p><?php endif; ?></div></article><?php endforeach; ?></div><?php if(!$nearbyCount): ?><p>Nearby places and distances have not been provided yet.</p><?php endif; ?></section>

<?php if($pricingDocuments): ?><dialog id="pd-document-viewer" class="pd-document-viewer" aria-labelledby="pd-document-viewer-title"><header><h2 id="pd-document-viewer-title">Pricing document</h2><button type="button" aria-label="Close document viewer"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="pd-document-viewer-body"></div><footer><a data-document-external target="_blank" rel="noopener">Open in new tab &nearr;</a><a data-document-download download>Download document</a></footer></dialog><?php endif; ?>
